package com.myeshopping.notification;
import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.concurrent.*;
@SpringBootApplication @RestController @RequestMapping("/api/v1/notifications") public class NotificationApplication { private final List<Map<String,Object>> sent=new CopyOnWriteArrayList<>(); public static void main(String[]a){SpringApplication.run(NotificationApplication.class,a);} @PostMapping public Map<String,Object> send(@RequestBody Map<String,Object> request){Map<String,Object> n=new LinkedHashMap<>(request);n.put("notificationId",UUID.randomUUID());n.put("status","SENT");n.put("sentAt",Instant.now());sent.add(n);return n;} @GetMapping public List<Map<String,Object>> all(){return sent;} }
